DECLARE @id bigint=?,@birth date=?,@name nvarchar(320)=?,@kana nvarchar(36)=?; SELECT s.student_id,s.row_version,s.student_no,s.student_name,CONVERT(char(10),s.birth_date,23),c.class_name FROM dbo.m_student s LEFT JOIN dbo.m_class c ON c.class_id=s.class_id WHERE s.is_deleted=0 AND (@id IS NULL OR s.student_id<>@id) AND s.birth_date=@birth AND (s.name_key=@name OR s.kana_key=@kana) ORDER BY s.student_id;
